items.command:
/bin/bash -lc "python3 -c 'import json
with open(\"sales-input.json\", encoding=\"utf-8\") as f:
    source = json.load(f)
integers = []
def collect(value):
    if isinstance(value, bool):
        return
    if isinstance(value, int):
        integers.append(value)
    elif isinstance(value, list):
        for item in value:
            collect(item)
    elif isinstance(value, dict):
        for item in value.values():
            collect(item)
collect(source)
if not integers:
    raise ValueError(\"sales-input.json 中没有整数\")
result = {\"total\": sum(integers), \"max\": max(integers)}
with open(\"analysis.json\", \"w\", encoding=\"utf-8\", newline=\"\") as f:
    json.dump(result, f, ensure_ascii=False, separators=(\",\", \":\"))
with open(\"analysis.json\", encoding=\"utf-8\", newline=\"\") as f:
    raw = f.read()
verified = json.loads(raw)
if verified "'!= result:
    raise AssertionError("读回结果与计算结果不一致")
print(f"整数个数: {len(integers)}")
print(f"计算结果: {result}")
print(f"读回结果: {verified}")
print(f"原始内容: {raw}")'"'"

